"use client"

import { revalidateLogic, useStore } from "@tanstack/react-form"
import { MailIcon } from "lucide-react"
import { type ReactNode, useEffect, useId, useRef } from "react"

import {
  Alert,
  AlertAction,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"
import { FormDialogError } from "@/components/openlmis/form-dialog/form-dialog"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import { FieldLabelText } from "@/components/openlmis/form-fields/form-fields"
import {
  SettingsItem,
  SettingsList,
  SettingsRowFrame,
} from "@/components/blocks/openlmis/settings-list"
import { StatusBadge } from "@/components/openlmis/status-badge"

import {
  type Profile,
  type ProfileFormValues,
  countProfileChanges,
  profileFormSchema,
  toProfileFormValues,
} from "@/components/openlmis/profile-page/profile"
import {
  type FormActionState as ProfileFormActions,
  FormActions as ProfileFormButtons,
} from "@/components/openlmis/form-actions"

type ProfileBasicInformationProps = {
  /** A skeleton of every row shows until it is set. */
  profile: Profile | undefined
  /** Called with the values when something changed; save them, then pass the saved profile back. */
  onSubmit: (values: ProfileFormValues, profile: Profile) => void
  /** Disables the buttons and shows a spinner while the profile is saved. */
  pending?: boolean
  /** Shown above the rows, e.g. why the save failed. */
  error?: ReactNode
  /** A new address waiting for its verification link to be opened. */
  pendingEmail?: string | null
  /** Sends the verification link again; Resend Link is hidden without it. */
  onResendEmail?: () => void
  resendPending?: boolean
  /** Tells the page how many fields have unsaved changes, e.g. to ask before leaving. */
  onChangesChange?: (changes: number) => void
  onCancel?: () => void
  /** Places Cancel and Save; by default they sit in a row under the form. */
  renderActions?: (actions: ProfileFormActions) => ReactNode
}

/** The user's own details as rows of settings: what an administrator set, then what they can edit. */
export function ProfileBasicInformation({
  profile,
  ...props
}: ProfileBasicInformationProps) {
  if (!profile) return <ProfileBasicInformationSkeleton />
  return <ProfileForm profile={profile} {...props} />
}

function ProfileForm({
  profile,
  onSubmit,
  pending = false,
  error,
  pendingEmail,
  onResendEmail,
  resendPending = false,
  onChangesChange,
  onCancel,
  renderActions,
}: ProfileBasicInformationProps & { profile: Profile }) {
  const formId = useId()
  const { user, contact } = profile
  const emailVerified = contact?.emailVerified ?? false
  const savedEmail = contact?.email ?? ""

  const form = useAppForm({
    defaultValues: toProfileFormValues(profile),
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: profileFormSchema },
    onSubmit: ({ value }) => onSubmit(value, profile),
  })
  // Only whether anything changed, so typing re-renders this page, not every part of it.
  const changes = useStore(form.store, (state) =>
    countProfileChanges(profile, state.values)
  )
  const changed = changes > 0

  const savedSignature = JSON.stringify([user.id, toProfileFormValues(profile)])
  const lastSaved = useRef(savedSignature)

  // Equivalent props must not replace a draft when a parent renders again.
  useEffect(() => {
    if (lastSaved.current === savedSignature) return
    lastSaved.current = savedSignature
    form.reset(toProfileFormValues(profile))
  }, [form, profile, savedSignature])
  useEffect(() => {
    onChangesChange?.(changes)
  }, [changes, onChangesChange])

  const actions: ProfileFormActions = {
    formId,
    changed,
    pending,
    cancel: () => {
      form.reset(toProfileFormValues(profile))
      onCancel?.()
    },
  }

  return (
    <>
      <form
        className="flex flex-col gap-4"
        id={formId}
        noValidate
        onSubmit={(event) => {
          event.preventDefault()
          if (changed) void form.handleSubmit()
        }}
      >
        {error && (
          <FormDialogError description={error} title="Could Not Save Profile" />
        )}
        {pendingEmail && (
          <Alert>
            <MailIcon />
            <AlertTitle>Email Change Pending</AlertTitle>
            <AlertDescription>
              {pendingEmail} is waiting to be verified. Open the link sent to it
              to start using it.
            </AlertDescription>
            {onResendEmail && (
              <AlertAction>
                <Button
                  disabled={resendPending}
                  onClick={onResendEmail}
                  size="sm"
                  type="button"
                  variant="outline"
                >
                  {resendPending && <Spinner data-icon="inline-start" />}
                  Resend Link
                </Button>
              </AlertAction>
            )}
          </Alert>
        )}
        <SettingsList>
          <SettingsItem label="Username">{user.username}</SettingsItem>
          <SettingsItem label="Job Title">
            {user.jobTitle || <None />}
          </SettingsItem>
          <SettingsItem label="Home Facility">
            {user.homeFacility || <None />}
          </SettingsItem>
          <form.AppField name="firstName">
            {(field) => (
              <field.TextField
                autoComplete="given-name"
                label="First Name"
                layout="row"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="lastName">
            {(field) => (
              <field.TextField
                autoComplete="family-name"
                label="Last Name"
                layout="row"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="email">
            {(field) => {
              const typed = field.state.value.trim()
              // The saved address shows whether it is verified; a new one, that it waits for its link.
              const isSaved = typed !== "" && typed === savedEmail
              return (
                <field.TextField
                  autoComplete="email"
                  badge={isSaved && <EmailStatus verified={emailVerified} />}
                  description={
                    typed &&
                    !isSaved &&
                    "A link to confirm this address will be sent to it. Your current address stays in use until then."
                  }
                  dir="ltr"
                  label="Email"
                  layout="row"
                  type="email"
                />
              )
            }}
          </form.AppField>
          <form.AppField name="phoneNumber">
            {(field) => (
              <field.TextField
                autoComplete="tel"
                dir="ltr"
                label="Phone Number"
                layout="row"
                type="tel"
              />
            )}
          </form.AppField>
          <form.Subscribe
            selector={(state) => state.values.email.trim() !== ""}
          >
            {(hasEmail) => (
              <form.AppField name="allowNotify">
                {(field) => (
                  <field.SwitchField
                    description={
                      emailVerified && hasEmail
                        ? "Get every notification your roles allow. Turn off to get none."
                        : "Verify your email address to turn this on."
                    }
                    disabled={!emailVerified || !hasEmail}
                    label="Allow Notifications"
                    layout="row"
                  />
                )}
              </form.AppField>
            )}
          </form.Subscribe>
        </SettingsList>
      </form>
      {renderActions ? (
        renderActions(actions)
      ) : (
        <div className="flex justify-end gap-2">
          <ProfileFormButtons actions={actions} saveLabel="Save Profile" />
        </div>
      )}
    </>
  )
}

function EmailStatus({ verified }: { verified: boolean }) {
  return verified ? (
    <StatusBadge tone="success">Verified</StatusBadge>
  ) : (
    <Badge variant="secondary">Not Verified</Badge>
  )
}

function None() {
  return <span className="text-muted-foreground">None</span>
}

const SKELETON_INPUTS = [
  { label: "First Name", required: true },
  { label: "Last Name", required: true },
  { label: "Email" },
  { label: "Phone Number" },
]

/** The rows while the profile loads: every row under its real label, with placeholders for the values. */
export function ProfileBasicInformationSkeleton() {
  return (
    <div aria-busy>
      <SettingsList>
        <SettingsItem label="Username">
          <SkeletonText className="w-24" />
        </SettingsItem>
        <SettingsItem label="Job Title">
          <SkeletonText className="w-32" />
        </SettingsItem>
        <SettingsItem label="Home Facility">
          <SkeletonText className="w-48" />
        </SettingsItem>
        {SKELETON_INPUTS.map(({ label, required }) => (
          <SettingsRowFrame
            key={label}
            label={
              <span className="text-sm">
                <FieldLabelText label={label} required={required} />
              </span>
            }
            value="control"
          >
            <Skeleton className="h-8 w-full" />
          </SettingsRowFrame>
        ))}
        <SettingsRowFrame
          description={
            <span className="flex h-5 items-center">
              <Skeleton className="h-3.5 w-64 max-w-full" />
            </span>
          }
          label={<span className="text-sm">Allow Notifications</span>}
        >
          {/* A plain element, since Skeleton owns its corner radius and a switch is round. */}
          <span className="h-4.5 w-8 animate-pulse rounded-full bg-muted" />
        </SettingsRowFrame>
      </SettingsList>
    </div>
  )
}

/** A bar inside one line of small text, so it takes the room the text will. */
function SkeletonText({ className }: { className: string }) {
  return (
    <span className="flex h-5 items-center justify-end">
      <Skeleton className={cn("h-3.5", className)} />
    </span>
  )
}

import { z } from "zod"

/** The signed-in user as the profile shows them; an administrator sets the read-only parts. */
export type ProfileUser = {
  id: string
  username: string
  firstName: string
  lastName: string
  jobTitle?: string | null
  /** The home facility as display text, e.g. "HC01 - Balaka District Hospital". */
  homeFacility?: string | null
}

export type ProfileContact = {
  email: string | null
  emailVerified: boolean
  phoneNumber: string | null
  allowNotify: boolean
}

/** The user and their contact details; a user without contact details has `null`. */
export type Profile = {
  user: ProfileUser
  contact: ProfileContact | null
}

const requiredText = (message: string) => z.string().trim().min(1, message)

export const profileFormSchema = z.object({
  firstName: requiredText("Enter a first name."),
  lastName: requiredText("Enter a last name."),
  email: z
    .string()
    .trim()
    .refine(
      (email) => email === "" || z.email().safeParse(email).success,
      "Enter a valid email address."
    ),
  phoneNumber: z.string(),
  allowNotify: z.boolean(),
})

export type ProfileFormValues = z.input<typeof profileFormSchema>

export function toProfileFormValues({
  user,
  contact,
}: Profile): ProfileFormValues {
  return {
    firstName: user.firstName,
    lastName: user.lastName,
    email: contact?.email ?? "",
    phoneNumber: contact?.phoneNumber ?? "",
    allowNotify: contact?.allowNotify ?? false,
  }
}

const orNull = (value: string) => value.trim() || null

/** Which parts of the profile the form changed, so a save sends only those. */
export function profileChanges(
  { user, contact }: Profile,
  values: ProfileFormValues
) {
  const email = orNull(values.email) !== (contact?.email ?? null)
  return {
    user:
      values.firstName.trim() !== user.firstName ||
      values.lastName.trim() !== user.lastName,
    contact:
      email ||
      orNull(values.phoneNumber) !== (contact?.phoneNumber ?? null) ||
      values.allowNotify !== (contact?.allowNotify ?? false),
    email,
  }
}

/** The profile as a successful save leaves it; a new email waits for its link, so the old one stays. */
export function applySaved(
  profile: Profile,
  values: ProfileFormValues
): Profile {
  const email = orNull(values.email)
  return {
    user: {
      ...profile.user,
      firstName: values.firstName.trim(),
      lastName: values.lastName.trim(),
    },
    contact: {
      email: profile.contact?.email ?? null,
      emailVerified: profile.contact?.emailVerified ?? false,
      phoneNumber: orNull(values.phoneNumber),
      // Nothing can be sent without an address, as the legacy UI has it.
      allowNotify: values.allowNotify && email !== null,
    },
  }
}

/** How many fields differ from the saved profile, e.g. for a discard prompt. */
export function countProfileChanges(
  profile: Profile,
  values: ProfileFormValues
): number {
  const saved = toProfileFormValues(profile)
  const keys = Object.keys(saved) as (keyof ProfileFormValues)[]
  return keys.filter((key) => {
    const before = saved[key]
    const after = values[key]
    return typeof before === "string" && typeof after === "string"
      ? before.trim() !== after.trim()
      : before !== after
  }).length
}

import { z } from "zod"

export const NOTIFICATION_CHANNELS = ["EMAIL", "SMS"] as const

export type NotificationChannel = (typeof NOTIFICATION_CHANNELS)[number]

/** A kind of notification that can be gathered into a digest, e.g. `requisition-actionRequired`. */
export type DigestConfiguration = {
  id: string
  tag: string
}

export type DigestSubscription = {
  digestConfiguration: { id: string }
  preferredChannel: NotificationChannel
  useDigest: boolean
  cronExpression?: string | null
}

export const FREQUENCIES = ["daily", "weekly", "custom"] as const

export type Frequency = (typeof FREQUENCIES)[number]

export const FREQUENCY_LABELS: Record<Frequency, string> = {
  daily: "Daily",
  weekly: "Weekly",
  custom: "Custom",
}

/** A schedule as the form edits it; `weekday` is Sunday 0 to Saturday 6, as in cron. */
const scheduleSchema = z.object({
  frequency: z.enum(FREQUENCIES),
  weekday: z.string(),
  time: z.string(),
  cron: z.string(),
})

const rowFields = z.object({
  configurationId: z.string(),
  tag: z.string(),
  channel: z.enum(NOTIFICATION_CHANNELS),
  useDigest: z.boolean(),
  schedule: scheduleSchema,
})

type Schedule = z.infer<typeof scheduleSchema>

export type DigestRow = z.infer<typeof rowFields>

export const WEEKDAYS = ["0", "1", "2", "3", "4", "5", "6"] as const

// Seconds, minutes, hours, day of month, month, day of week: the Spring cron OpenLMIS reads.
const SIMPLE_CRON = /^0 (\d{1,2}) (\d{1,2}) \* \* (\*|[0-6])$/
const CRON_FIELD = /^[\dA-Za-z*?/,#-]+$/
const TIME = /^(\d{2}):(\d{2})$/

const pad = (value: number) => String(value).padStart(2, "0")

/** Daily or weekly at a time when the expression is that simple, otherwise custom. */
export function parseSchedule(cron: string | null | undefined): Schedule {
  if (!cron)
    return { frequency: "daily", weekday: "0", time: "08:00", cron: "" }
  const [, minute, hour, weekday] = SIMPLE_CRON.exec(cron) ?? []
  if (
    !minute ||
    !hour ||
    !weekday ||
    Number(minute) > 59 ||
    Number(hour) > 23
  ) {
    return { frequency: "custom", weekday: "0", time: "08:00", cron }
  }
  return {
    frequency: weekday === "*" ? "daily" : "weekly",
    weekday: weekday === "*" ? "0" : weekday,
    time: `${pad(Number(hour))}:${pad(Number(minute))}`,
    cron,
  }
}

export function toCron({ frequency, weekday, time, cron }: Schedule): string {
  if (frequency === "custom") return cron.trim()
  const [, hour = "0", minute = "0"] = TIME.exec(time) ?? []
  return `0 ${Number(minute)} ${Number(hour)} * * ${frequency === "daily" ? "*" : weekday}`
}

/** Six fields of cron characters; the server checks the values themselves. */
export function isValidCron(cron: string): boolean {
  const fields = cron.trim().split(/\s+/)
  return fields.length === 6 && fields.every((field) => CRON_FIELD.test(field))
}

/** `requisition-actionRequired` as "Requisition - Action Required". */
export function tagLabel(tag: string): string {
  return tag
    .split("-")
    .map((part) =>
      part
        .replace(/([a-z])([A-Z])/g, "$1 $2")
        .replace(/(^|\s)\S/g, (letter) => letter.toUpperCase())
    )
    .join(" - ")
}

/** One row per configuration; one the user never subscribed to is email without a digest. */
export function toDigestRows(
  configurations: readonly DigestConfiguration[],
  subscriptions: readonly DigestSubscription[]
): DigestRow[] {
  const byId = new Map(
    subscriptions.map((item) => [item.digestConfiguration.id, item])
  )
  return configurations.map(({ id, tag }) => {
    const subscription = byId.get(id)
    return {
      configurationId: id,
      tag,
      channel: subscription?.preferredChannel ?? "EMAIL",
      useDigest: subscription?.useDigest ?? false,
      schedule: parseSchedule(subscription?.cronExpression),
    }
  })
}

export function toSubscriptions(
  rows: readonly DigestRow[]
): DigestSubscription[] {
  return rows.map(({ configurationId, channel, useDigest, schedule }) => ({
    digestConfiguration: { id: configurationId },
    preferredChannel: channel,
    useDigest,
    ...(useDigest && { cronExpression: toCron(schedule) }),
  }))
}

/** How many notifications would save differently from how they were loaded. */
export function countDigestChanges(
  saved: readonly DigestRow[],
  rows: readonly DigestRow[]
): number {
  const before = toSubscriptions(saved).map((item) => JSON.stringify(item))
  return toSubscriptions(rows).filter(
    (item, index) => JSON.stringify(item) !== before[index]
  ).length
}

const rowSchema = rowFields.superRefine(
  ({ useDigest, channel, schedule }, context) => {
    if (!useDigest) return
    if (channel !== "EMAIL") {
      context.addIssue({
        code: "custom",
        path: ["channel"],
        message: "Digests are sent by email only.",
      })
    }
    if (schedule.frequency === "custom") {
      if (!isValidCron(schedule.cron)) {
        context.addIssue({
          code: "custom",
          path: ["schedule", "cron"],
          message:
            "Enter six fields: seconds, minutes, hours, day, month and weekday.",
        })
      }
    } else if (!TIME.test(schedule.time)) {
      context.addIssue({
        code: "custom",
        path: ["schedule", "time"],
        message: "Enter a time.",
      })
    }
  }
)

export const digestFormSchema = z.object({ rows: z.array(rowSchema) })

